grpc.protoSchema:
syntax = "proto3";
package service.v1;

import "google/protobuf/wrappers.proto";

// Service definition for ServiceV1
service ServiceV1 {
  rpc QueryGetCards(QueryGetCardsRequest) returns (QueryGetCardsResponse) {}
}

// Wrapper message for a list of Card.
message ListOfCard {
  message List {
    repeated Card items = 1;
  }
  List list = 1;
}
// Request message for getCards operation.
message QueryGetCardsRequest {
  string user_id = 1;
}
// Response message for getCards operation.
message QueryGetCardsResponse {
  ListOfCard get_cards = 1;
}

message Card {
  string user_id = 1;
  google.protobuf.StringValue card_id = 2;
  google.protobuf.StringValue card_expiry = 3;
}

